function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function levelWord(l){ return ({'beginner':'初学者','elementary':'初级','intermediate':'中级','advanced':'高级','expert':'专家'})[String(l||'').toLowerCase()]||'中级'; }
function styleWord(s){ return ({'socratic':'苏格拉底式提问','guided':'引导式脚手架','direct':'直接讲解','inquiry':'探究式'})[String(s||'').toLowerCase()]||'苏格拉底式提问'; }
function buildTutorPrompt(o){
  o=o||{};
  var subject=String(o.subject||'').trim()||'（待填写学科）';
  var topic=String(o.topic||'').trim()||'（待填写主题）';
  var goal=String(o.goal||'').trim()||'（待填写学习目标）';
  var level=levelWord(o.level);
  var style=styleWord(o.style);
  var lang=String(o.lang||'中文').trim()||'中文';
  var examples=splitLines(o.examples);
  var lines=[];
  lines.push('# 辅导 Agent 角色卡：'+subject+' · '+topic);
  lines.push('');
  lines.push('## 角色');
  lines.push('你是一位'+subject+'的'+level+'辅导老师，专长「'+topic+'」。用'+lang+'与学生交流。');
  lines.push('');
  lines.push('## 目标');
  lines.push('帮助学生达成：'+goal);
  lines.push('');
  lines.push('## 教学方法（'+style+'）');
  lines.push('- 先诊断学生的已有理解与误区，再决定从哪里搭脚手架');
  lines.push('- 不直接给最终答案；用层层提问引导学生自己推出来');
  lines.push('- 把大任务拆成小步骤，每步给即时、具体的反馈');
  lines.push('- 用生活化类比降低抽象概念的门槛');
  lines.push('');
  lines.push('## 约束');
  lines.push('- 不代替学生完成作业或考试；只教方法、不给成品');
  lines.push('- 学生答错时先肯定思考，再指出卡点，避免打击信心');
  lines.push('- 遇超出范围或敏感问题，礼貌说明边界并建议求助真人老师');
  lines.push('');
  lines.push('## 开场示例');
  lines.push('老师：我们先聊聊你对「'+topic+'」已经知道什么？能举个例子吗？');
  if(examples.length){ lines.push(''); lines.push('## 参考样例'); examples.forEach(function(e){ lines.push('- '+e); }); }
  return {title:subject+'/'+topic+' 辅导角色卡', level:level, style:style, hasGoal:goal.indexOf('（待填写')<0, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, levelWord:levelWord, styleWord:styleWord, buildTutorPrompt:buildTutorPrompt};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AgentTutorPromptForgePure = EXPORTS; }
